// ---------------------------------------------------------------- Typography (typography.*)

/** CSS half-leading: center glyphs in the line box, no trimming (tokens.md §9). */
private val CssLineHeight = LineHeightStyle(LineHeightStyle.Alignment.Center, LineHeightStyle.Trim.None)

/**
 * Semantic text styles. [uppercase] styles must be rendered with `text.uppercase(locale)`;
 * tabular figures are already in the TextStyle (`tnum`).
 */
enum class BBTextStyle(val style: TextStyle, val uppercase: Boolean) {
    /** SimulationResult figure: font-heading text-4xl font-medium leading-none tracking-tight tabular-nums */
    Display(
        TextStyle(
            fontFamily = BBFontFamilies.sans,
            fontWeight = FontWeight.W500,
            fontSize = 36.sp,
            lineHeight = 36.sp,
            letterSpacing = (-0.025).em,
            fontFeatureSettings = "tnum",
            lineHeightStyle = CssLineHeight,
        ),
        uppercase = false,
    ),
    /** PAGE_TITLE: font-display font-light text-[2.5rem] leading-[0.95] */
    PageTitle(
        TextStyle(
            fontFamily = BBFontFamilies.display,
            fontWeight = FontWeight.W300,
            fontSize = 40.sp,
            lineHeight = 38.sp,
            letterSpacing = 0.0.em,
            lineHeightStyle = CssLineHeight,
        ),
        uppercase = false,
    ),
    /** StatCard value (font-heading text-3xl font-medium tabular-nums) */
