            fontSize = 24.sp,
            lineHeight = 32.sp,
            letterSpacing = 0.0.em,
            fontFeatureSettings = "tnum",
            lineHeightStyle = CssLineHeight,
        ),
        uppercase = false,
    ),
    /** SECTION_TITLE: font-display font-light text-[2.25rem] leading-[0.95]; no icon next to it */
