// ---------------------------------------------------------------- Motion

/** Mass-spring-damper parameters (same equation as the web). */
data class BBSpring(val stiffness: Float, val damping: Float, val mass: Float, val dampingRatio: Float, val settleMs: Int) {
    /** Compose assumes mass 1, so stiffness is divided by mass (tokens.md §6.1). */
    fun <T> spec(): SpringSpec<T> = spring(dampingRatio = dampingRatio, stiffness = stiffness / mass)
}

